def create_advanced_prompt(task, context, examples, constraints, format=""):
    prompt = f"""You are an expert AI assistant. Your task is: {task}

Context: {context}

Examples:
{examples}

Constraints: {constraints}

Please provide your response in {format} format:"""
    return prompt

# Example usage
task = "Summarize the key points of the provided article"
context = "Article about climate change impacts"
examples = "1. Input: [article text] Output: [3-5 bullet points]"
constraints = "Keep under 200 words, focus on impacts only"

prompt = create_advanced_prompt(task, context, examples, constraints)
print(prompt)
